import assert from 'node:assert/strict';import Worker from '../dist/server/index.js';import {fixture} from './friend-server.mjs';const f=fixture();async function call(i,path,method='GET',body){const r=await Worker.fetch(new Request('https://events.test'+path,{method,headers:{'oai-authenticated-user-id':'race-'+i,'X-Kanji-Device':String(i).padStart(32,'0'),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})}),f.env);const value=await r.json();assert.equal(r.status,200,JSON.stringify(value));return value;}try{const count=100;for(let i=0;i<count;i++)await call(i,'/api/profile','PUT',{name:'記録テスト'+i,char:'一',frame:'plain',color:'gold',glow:'none'});const event={id:'same_event_across_players_001',items:['一','山','小'].map((char,n)=>({char,shots:n?0:1,kills:n?0:1,bestShot:n?0:1,survived:true})),shots:1,survivors:3,outcome:'win',challenge:null,cleared:false};await Promise.all(Array.from({length:count*5},(_,i)=>call(i%count,'/api/play-progress','POST',{events:[event]})));assert.equal(f.sqlite.prepare('SELECT COUNT(*) n FROM play_events').get().n,count);assert.equal(f.sqlite.prepare('SELECT SUM(plays) n FROM play_usage').get().n,count*3);assert.equal(f.sqlite.prepare('SELECT MAX(plays) n FROM play_usage').get().n,1);console.log('PASS 100 players x 5 concurrent copies: 500 submissions, 100 event ledgers, 300 character-use counts, no double count or cross-player deduplication.');}finally{f.sqlite.close();}
